exports.render = page => {
  const sec = lang => { const [title, paras] = PAGES[page][lang]; return `<section lang="${lang}" id="${lang}"><h1>${title}</h1>\n${paras.map(p => `<p>${esc(p)}</p>`).join('\n')}</section>`; };
  return `<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${PAGES[page].en[0]} · Homebrief</title><link rel="icon" href="/icon.svg" type="image/svg+xml"><link rel="stylesheet" href="/landing.css"></head>\n<body><main class="wrap page" style="padding-top:32px;max-width:760px"><p><a href="/">← Homebrief</a> · <a href="#en">English</a> · <a href="#ko">한국어</a></p>\n${sec('en')}\n<hr>\n${sec('ko')}\n</main></body></html>\n`;
};
exports.PAGES = PAGES;
